// Update a persona's config (activity_policy, modes, status, voice).
// =====================================================================
func (q *Queries) UpdateAIPersona(ctx context.Context, arg UpdateAIPersonaParams) (AiPersona, error) {
	row := q.db.QueryRow(ctx, updateAIPersona,
		arg.DisclosureMode,
		arg.AutonomyMode,
		arg.VoiceID,
		arg.VoicePrompt,
		arg.ActivityPolicy,
		arg.Status,
		arg.ID,
	)
	var i AiPersona
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.ProfileID,
		&i.DisclosureMode,
		&i.AutonomyMode,
		&i.VoicePrompt,
		&i.ActivityPolicy,
		&i.Status,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.VoiceID,
	)
	return i, err
}

const updatePersonaVoice = `-- name: UpdatePersonaVoice :one
UPDATE persona_voices
SET
 name = COALESCE($1, name),
 slug = COALESCE($2, slug),
 description = COALESCE($3, description),
 voice_prompt = COALESCE($4, voice_prompt),
 is_system = COALESCE($5, is_system),
 updated_at = now()
WHERE id = $6
RETURNING id, name, slug, description, voice_prompt, is_system, created_by, created_at, updated_at
`

type UpdatePersonaVoiceParams struct {
	Name        *string     `json:"name"`
	Slug        *string     `json:"slug"`
	Description *string     `json:"description"`
	VoicePrompt *string     `json:"voice_prompt"`
	IsSystem    *bool       `json:"is_system"`
	ID          pgtype.UUID `json:"id"`
}

func (q *Queries) UpdatePersonaVoice(ctx context.Context, arg UpdatePersonaVoiceParams) (PersonaVoice, error) {
	row := q.db.QueryRow(ctx, updatePersonaVoice,
		arg.Name,
		arg.Slug,
		arg.Description,
		arg.VoicePrompt,
		arg.IsSystem,
		arg.ID,
	)
	var i PersonaVoice
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Slug,
		&i.Description,
		&i.VoicePrompt,
		&i.IsSystem,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
